"""The self-maps of S^n are exactly the signed permutations: |Z2Map(S^n,S^n)| = |B_{n+1}|."""
from __future__ import annotations
from itertools import permutations, product
from math import factorial
from typing import List, Tuple

def selfmap_count_closed(n: int) -> int:
    """2^(n+1) * (n+1)! via the falling factorial on the diagonal m = n."""
    ff = 1
    for i in range(n + 1):
        ff *= (n + 1 - i)          # = (n+1)!
    return 2 ** (n + 1) * ff

def hyperoctahedral_order(k: int) -> int:
    """|B_k| = 2^k * k!, the order of the signed-permutation group."""
    return 2 ** k * factorial(k)

def signed_permutations(k: int) -> List[Tuple[Tuple[int, int], ...]]:
    """Enumerate all signed permutations of k axes as (image_axis, sign) tuples."""
    out = []
    for perm in permutations(range(k)):
        for signs in product((1, -1), repeat=k):
            out.append(tuple((perm[i], signs[i]) for i in range(k)))
    return out

if __name__ == "__main__":
    for n in range(5):
        c = selfmap_count_closed(n)
        b = hyperoctahedral_order(n + 1)
        realized = len(signed_permutations(n + 1)) if n <= 3 else b
        print(f"n={n}: self-maps={c:>6}  |B_{n+1}|={b:>6}  enumerated={realized:>6}  equal={c==b==realized}")

"""Suspension separates the stable (existence/excess) from the unstable (count)."""
from __future__ import annotations

def falling_factorial(base: int, length: int) -> int:
    r = 1
    for i in range(length):
        r *= (base - i)
    return r

def count(m: int, n: int) -> int:
    ff = falling_factorial(n + 1, m + 1)
    return 2 ** (m + 1) * ff if ff > 0 else 0

def coindex(n: int, up_to: int = 20) -> int:
    """Largest m admitting a Z2-map S^m -> S^n; provably equals n."""
    return max((m for m in range(up_to + 1) if count(m, n) > 0), default=-1)

if __name__ == "__main__":
    print("Excess n-m is invariant; the count is not (it scales by 2(n+2) per suspension).")
    m, n = 1, 2
    for _ in range(6):
        c0, c1 = count(m, n), count(m + 1, n + 1)
        print(f"S^{m}->S^{n}: count={c0:>8}  excess={n-m}  |  "
              f"suspended S^{m+1}->S^{n+1}: count={c1:>9}  ratio={c1//c0} = 2(n+2)={2*(n+2)}")
        m, n = m + 1, n + 1
    print()
    for n in range(6):
        print(f"coind(S^{n}) = {coindex(n)}  (Borsuk-Ulam: no map S^{n+1} -> S^{n})")

