def count_closed_form(m: int, n: int) -> int:
    """Exact number of Z2-maps S^m -> S^n = 2^(m+1) * (n+1)^{falling(m+1)}."""
    ff: int = 1
    for i in range(m + 1):
        factor: int = (n + 1) - i
        if factor <= 0:
            return 0            # m > n: Borsuk-Ulam obstruction
        ff *= factor
    return 2 ** (m + 1) * ff

