from itertools import permutations, product
from typing import Iterator, Tuple

Vertex = Tuple[int, int]

def enumerate_maps(m: int, n: int) -> Iterator[Tuple[Vertex, ...]]:
    """Yield each Z2-map S^m -> S^n as its positive-vertex data."""
    for injection in permutations(range(n + 1), m + 1):
        for signs in product((1, -1), repeat=m + 1):
            yield tuple((injection[i], signs[i]) for i in range(m + 1))

