function COUNT_BRUTE(m, n):
    targets <- { (axis, sign) : axis in 0..n, sign in {+1,-1} }
    total <- 0
    for data in targets^(m+1):
        axes <- [ v.axis for v in data ]
        if all axes distinct:            # induced map is simplicial
            total <- total + 1
    return total
